import React, { ReactElement, useEffect, useRef } from 'react';
import { isElement } from 'react-is';

import {
  DEFAULT_TOOLTIP_MIN_WIDTH,
  ScrollableContainerParent,
  StyledTooltipContainer,
  TooltipItems,
  TooltipItemsContainer,
} from './InteractiveChartTooltip.styles.js';
import { Flex } from '../../../../../../layouts-core/flex/Flex.js';
import { useHandleSetScrollbar } from '../hooks/useHandleSetScrollbar.js';

interface ChartTooltipSeriesProps {
  pinned?: boolean;
  header?: ReactElement;
  body?: ReactElement[];
  pointerEvents: boolean;
  onScrollContent?: (event: Event) => void;
}

/**
 * Component handling how series are displayed inside the tooltip
 */
export const InteractiveChartTooltipSeries = (
  props: ChartTooltipSeriesProps,
) => {
  const { header, body, pointerEvents, onScrollContent } = props;
  const scrollRef = useRef<HTMLDivElement>(null);
  const scrollRefContainer = useRef<HTMLDivElement>(null);

  useHandleSetScrollbar(body?.length ?? 0);

  useEffect(() => {
    if (!onScrollContent) {
      return;
    }
    scrollRefContainer.current?.addEventListener('scroll', onScrollContent);

    return () => {
      scrollRefContainer.current?.removeEventListener(
        'scroll',
        onScrollContent,
      );
    };
  }, []);

  const items = isElement(body)
    ? body.props.children
    : React.Children.toArray(body);

  return (
    <StyledTooltipContainer
      minWidth={DEFAULT_TOOLTIP_MIN_WIDTH}
      allowPointerEvents={pointerEvents}
    >
      <Flex gap={0} flexDirection="column">
        {header}
        <ScrollableContainerParent
          ref={scrollRefContainer}
          data-testid="chart-tooltip-item-container"
        >
          <TooltipItemsContainer ref={scrollRef}>
            <TooltipItems data-testid="chart-tooltip-item">
              {items}
            </TooltipItems>
          </TooltipItemsContainer>
        </ScrollableContainerParent>
      </Flex>
    </StyledTooltipContainer>
  );
};

InteractiveChartTooltipSeries['displayName'] = 'InteractiveChartTooltipSeries';
